// Generated by scripts/build-glossary-data.mjs from content-source/glossary. Do not edit by hand.
// [slug, name, one-line definition, category, written in this locale (1) or English fallback (0)], sorted by name.
export const GLOSSARY_INDEX = Object.freeze({"locale":"vi","terms":[["airdrop","Airdrop","Airdrop là việc một dự án phát token miễn phí vào ví của người dùng đủ điều kiện, thường để thưởng người dùng sớm, phân phối token rộng hơn hoặc quảng bá dự án.","basics",1],["altcoin","Altcoin","Altcoin là cách gọi chung mọi đồng tiền mã hóa không phải Bitcoin, từ các dự án lớn như Ethereum, Solana đến những token nhỏ mới niêm yết.","basics",1],["aml","AML (phòng chống rửa tiền)","AML là tập hợp quy định và quy trình mà sàn giao dịch và tổ chức tài chính áp dụng để phát hiện, ngăn chặn và báo cáo hoạt động rửa tiền hoặc tài trợ khủng bố.","regulation",1],["apr-vs-apy","APR và APY","APR là lãi suất năm chưa tính lãi kép, còn APY là lợi suất năm đã tính lãi kép; cùng một mức lãi, APY luôn bằng hoặc cao hơn APR nếu lãi được cộng dồn.","defi",1],["arbitrage","Arbitrage (Kinh doanh chênh lệch giá)","Arbitrage là chiến lược kiếm lời từ chênh lệch giá của cùng một tài sản giữa hai thị trường, bằng cách mua ở nơi rẻ và bán ở nơi đắt gần như cùng lúc.","trading",1],["funding-rate-arbitrage","Arbitrage funding rate (Kinh doanh chênh lệch funding)","Arbitrage funding rate là chiến lược giữ vị thế trung lập về giá, thường là mua spot và short perpetual cùng lượng, để thu khoản funding được trả định kỳ.","derivatives",1],["short-selling","Bán khống (Short selling)","Bán khống là việc bán một tài sản bạn không sở hữu, bằng cách vay hoặc dùng hợp đồng phái sinh, với kỳ vọng mua lại ở giá thấp hơn để kiếm lời.","derivatives",1],["futures-basis","Basis hợp đồng tương lai (Futures basis)","Basis là chênh lệch giữa giá hợp đồng tương lai và giá spot (hoặc giá chỉ số) của cùng một tài sản, thường được thể hiện bằng số tiền hoặc tỷ lệ phần trăm năm.","derivatives",1],["proof-of-stake","Bằng chứng cổ phần (Proof of Stake - PoS)","Bằng chứng cổ phần (Proof of Stake, PoS) là cơ chế đồng thuận trong đó validator khóa coin của mạng làm tài sản đảm bảo để được quyền đề xuất và xác thực khối mới, thay cho việc đào bằng máy.","basics",1],["proof-of-work","Bằng chứng công việc (Proof of Work - PoW)","Bằng chứng công việc (Proof of Work, PoW) là cơ chế đồng thuận trong đó thợ đào dùng sức mạnh tính toán để giải bài toán mật mã, ai tìm ra lời giải trước sẽ được thêm khối mới và nhận thưởng.","basics",1],["proof-of-reserves","Bằng chứng dự trữ (Proof of reserves)","Bằng chứng dự trữ là báo cáo sàn công bố để chứng minh họ đang nắm giữ đủ tài sản on-chain tương ứng với số dư khách hàng, thường kèm cách để từng người tự kiểm tra.","wallets-security",1],["volatility","Biến động giá (Volatility)","Biến động giá (volatility) là mức độ và tốc độ thay đổi giá của một tài sản trong một khoảng thời gian; biến động càng cao thì giá dao động lên xuống càng mạnh.","basics",1],["candlestick-chart","Biểu đồ nến (Candlestick chart)","Biểu đồ nến là loại biểu đồ giá trong đó mỗi cây nến thể hiện giá mở cửa, giá cao nhất, giá thấp nhất và giá đóng cửa của một tài sản trong một khung thời gian.","trading",1],["bitcoin","Bitcoin (BTC)","Bitcoin (BTC) là đồng tiền mã hóa đầu tiên, ra đời năm 2009, chạy trên blockchain riêng dùng cơ chế bằng chứng công việc và có tổng cung tối đa cố định 21 triệu đồng.","basics",1],["bitcoin-halving","Bitcoin halving (sự kiện giảm một nửa)","Bitcoin halving là sự kiện được lập trình sẵn, cứ mỗi 210.000 khối (khoảng 4 năm) thì phần thưởng khối cho thợ đào giảm đi một nửa, làm chậm tốc độ phát hành BTC mới.","basics",1],["block-explorer","Block explorer (trình khám phá khối)","Block explorer là trang web cho phép bạn tra cứu mọi giao dịch, địa chỉ ví và khối trên một blockchain, giống như công cụ tra cứu sao kê công khai của mạng đó.","onchain",1],["blockchain","Blockchain (chuỗi khối)","Blockchain (chuỗi khối) là một sổ cái số được chia sẻ, trong đó các giao dịch được gom thành từng khối và nối với nhau theo thứ tự, nên muốn sửa dữ liệu cũ thì phải làm lại toàn bộ các khối phía sau.","basics",1],["grid-trading-bot","Bot giao dịch lưới (grid bot)","Bot giao dịch lưới là công cụ tự động đặt sẵn nhiều lệnh mua và bán ở các mức giá cách đều trong một vùng, để kiếm lời từ những lần giá dao động lên xuống.","exchange-features",1],["whale","Cá voi (Whale)","Cá voi (whale) là cá nhân hoặc tổ chức nắm giữ lượng lớn một loại tiền mã hóa, đủ để các giao dịch của họ có thể ảnh hưởng tới giá hoặc thanh khoản.","trading",1],["trading-pair","Cặp giao dịch (Trading pair)","Cặp giao dịch (trading pair) là hai tài sản được mua bán trực tiếp với nhau trên sàn, ví dụ BTC/USDT, trong đó đồng đứng trước là tài sản cơ sở và đồng đứng sau là đồng định giá.","trading",1],["token-approval","Cấp quyền token (Token approval)","Cấp quyền token là thao tác cho phép một hợp đồng thông minh được chi tiêu một lượng token nhất định trong ví của bạn, bắt buộc trước khi swap hay gửi token vào nhiều ứng dụng DeFi.","wallets-security",1],["vip-tier","Cấp VIP (bậc phí giao dịch)","Cấp VIP là hệ thống bậc phí của sàn, trong đó người dùng có khối lượng giao dịch hoặc số dư tài sản lớn hơn được hưởng mức phí maker và taker thấp hơn.","exchange-features",1],["cross-chain-bridge","Cầu nối chuỗi chéo (Cross-chain bridge)","Cầu nối chuỗi chéo là giao thức giúp chuyển tài sản hoặc dữ liệu giữa hai blockchain khác nhau, thường bằng cách khóa tài sản ở chuỗi gốc và phát hành bản đại diện ở chuỗi đích.","defi",1],["cbdc","CBDC (tiền kỹ thuật số của ngân hàng trung ương)","CBDC là dạng tiền pháp định kỹ thuật số do chính ngân hàng trung ương phát hành và bảo đảm, có giá trị ngang tiền mặt của quốc gia đó.","stablecoins",1],["bid-ask-spread","Chênh lệch giá mua-bán (Spread)","Chênh lệch giá mua-bán (bid-ask spread) là khoảng cách giữa giá mua cao nhất (bid) và giá bán thấp nhất (ask) trong sổ lệnh, và là chi phí ngầm mỗi khi bạn mua rồi bán ngay bằng lệnh thị trường.","trading",1],["fear-and-greed-index","Chỉ số Sợ hãi và Tham lam (Fear and Greed Index)","Chỉ số Sợ hãi và Tham lam là thang điểm từ 0 đến 100 tóm tắt tâm lý thị trường crypto, trong đó điểm thấp thể hiện sợ hãi và điểm cao thể hiện tham lam.","onchain",1],["defi-lending","Cho vay DeFi (DeFi lending)","Cho vay DeFi là việc gửi crypto vào giao thức như Aave để nhận lãi, hoặc thế chấp crypto để vay tài sản khác, toàn bộ do hợp đồng thông minh quản lý thay cho ngân hàng.","defi",1],["instant-convert","Chuyển đổi nhanh (Convert)","Chuyển đổi nhanh là tính năng cho phép bạn đổi một crypto sang crypto khác với giá báo trước cố định, chỉ bằng một nút bấm, không cần dùng sổ lệnh.","exchange-features",1],["coin-vs-token","Coin và token (Coin vs token)","Coin là tài sản gốc của một blockchain riêng như BTC hay ETH, còn token là tài sản được tạo trên một blockchain có sẵn thông qua hợp đồng thông minh, như USDT trên Ethereum hay Tron.","basics",1],["copy-trading","Copy trade (sao chép giao dịch)","Copy trade là tính năng cho phép bạn tự động sao chép các lệnh của một nhà giao dịch khác, gọi là trader dẫn dắt, theo tỷ lệ vốn mà bạn phân bổ.","exchange-features",1],["tokenized-stocks","Cổ phiếu token hóa (tokenized stocks)","Cổ phiếu token hóa là token đại diện cho giá trị của một cổ phiếu niêm yết như Apple hay Tesla, thường được bảo chứng bởi cổ phiếu thật do một đơn vị lưu ký nắm giữ.","tokenized-assets",1],["fiat-on-ramp","Cổng nạp tiền pháp định (fiat on-ramp)","Cổng nạp tiền pháp định là dịch vụ cho phép bạn đổi tiền như VND hay USD thành crypto, qua chuyển khoản ngân hàng, thẻ, ví điện tử hoặc giao dịch P2P.","regulation",1],["seed-phrase","Cụm từ khôi phục (Seed phrase)","Cụm từ khôi phục là chuỗi 12 hoặc 24 từ tiếng Anh dùng để tạo lại toàn bộ khóa riêng tư của ví, nên ai có nó là có toàn quyền với tài sản trong ví.","wallets-security",1],["withdrawal-whitelist","Danh sách trắng rút tiền (Withdrawal whitelist)","Danh sách trắng rút tiền là tính năng bảo mật chỉ cho phép tài khoản sàn rút crypto đến những địa chỉ bạn đã lưu và xác minh trước.","wallets-security",1],["dao","DAO (Tổ chức tự trị phi tập trung)","DAO là tổ chức tự trị phi tập trung, nơi quy tắc và quỹ chung được quản lý bằng hợp đồng thông minh, còn các quyết định được thành viên bỏ phiếu, thường bằng token quản trị.","defi",1],["dollar-cost-averaging","DCA (Trung bình giá)","DCA (dollar-cost averaging) là chiến lược mua một số tiền cố định của một tài sản theo lịch đều đặn, bất kể giá lên hay xuống, để làm mềm tác động của biến động giá.","trading",1],["defi","DeFi (Tài chính phi tập trung)","DeFi (tài chính phi tập trung) là các dịch vụ tài chính như giao dịch, cho vay, gửi tiết kiệm chạy bằng hợp đồng thông minh trên blockchain, không cần ngân hàng hay sàn tập trung làm trung gian.","defi",1],["depeg","Depeg (mất neo giá)","Depeg là tình trạng một stablecoin hoặc token được neo giá rời khỏi mức giá mục tiêu của nó, ví dụ USDT hay USDC giao dịch ở 0,97 USD thay vì 1 USD.","stablecoins",1],["exchange-netflow","Dòng tiền vào ra sàn (exchange netflow)","Dòng tiền vào ra sàn là chỉ số on-chain đo lượng coin chuyển vào ví sàn trừ đi lượng coin rút ra khỏi sàn trong một khoảng thời gian.","onchain",1],["mining","Đào coin (Crypto mining)","Đào coin (crypto mining) là quá trình dùng máy tính chuyên dụng giải bài toán mật mã để xác nhận giao dịch, thêm khối mới vào blockchain bằng chứng công việc và nhận coin mới làm phần thưởng.","basics",1],["address-poisoning","Đầu độc địa chỉ (Address poisoning)","Đầu độc địa chỉ là chiêu lừa đảo gửi giao dịch nhỏ từ một địa chỉ có đầu và cuối giống địa chỉ bạn hay dùng, để bạn sao chép nhầm từ lịch sử giao dịch và chuyển tiền cho kẻ gian.","wallets-security",1],["dual-investment","Đầu tư kép (dual investment)","Đầu tư kép là sản phẩm có cấu trúc cho lợi suất cao trong thời gian ngắn, nhưng khi đáo hạn bạn có thể nhận lại tài sản ban đầu hoặc một tài sản khác tùy giá so với giá mục tiêu.","exchange-features",1],["active-addresses","Địa chỉ hoạt động (active addresses)","Địa chỉ hoạt động là số địa chỉ ví riêng biệt có gửi hoặc nhận giao dịch thành công trên một blockchain trong một khoảng thời gian, thường là một ngày.","onchain",1],["wallet-address","Địa chỉ ví (Wallet address)","Địa chỉ ví là chuỗi ký tự công khai đại diện cho nơi nhận crypto trên một blockchain cụ thể, giống số tài khoản ngân hàng nhưng gắn với từng mạng lưới.","wallets-security",1],["fully-diluted-valuation","Định giá pha loãng hoàn toàn (FDV)","Định giá pha loãng hoàn toàn (FDV) là giá hiện tại của token nhân với tổng cung tối đa, cho biết dự án sẽ được định giá bao nhiêu nếu toàn bộ token đã được phát hành.","basics",1],["all-time-high","Đỉnh lịch sử (All-time high - ATH)","Đỉnh lịch sử (all-time high, ATH) là mức giá cao nhất mà một tài sản từng đạt được kể từ khi bắt đầu giao dịch, thường được tính theo một đồng tiền định giá như USD hoặc USDT.","basics",1],["leverage","Đòn bẩy (Leverage)","Đòn bẩy là việc dùng một khoản ký quỹ nhỏ để mở vị thế có giá trị lớn hơn nhiều lần, làm phóng đại cả lợi nhuận lẫn thua lỗ.","derivatives",1],["synthetic-dollar","Đô la tổng hợp (stablecoin delta trung tính)","Đô la tổng hợp là token giữ giá quanh 1 USD bằng cách nắm giữ crypto đồng thời mở vị thế short tương ứng trên hợp đồng vĩnh cửu, để lãi lỗ hai bên triệt tiêu nhau.","stablecoins",1],["token-burn","Đốt token (Token burn)","Đốt token (token burn) là việc gửi token tới một địa chỉ không ai có thể truy cập hoặc hủy chúng bằng hợp đồng, khiến lượng token đó bị loại vĩnh viễn khỏi nguồn cung.","basics",1],["crypto-earn","Earn (sản phẩm tiết kiệm crypto)","Earn là nhóm sản phẩm trên sàn cho phép bạn gửi crypto để nhận lãi, gồm gửi linh hoạt, gửi kỳ hạn, staking và các sản phẩm có cấu trúc.","exchange-features",1],["spot-bitcoin-etf","ETF Bitcoin giao ngay (spot Bitcoin ETF)","ETF Bitcoin giao ngay là quỹ hoán đổi danh mục niêm yết trên sàn chứng khoán, nắm giữ BTC thật và cho nhà đầu tư tiếp xúc với giá Bitcoin qua tài khoản chứng khoán.","regulation",1],["ethereum","Ethereum (ETH)","Ethereum là blockchain cho phép chạy hợp đồng thông minh và ứng dụng phi tập trung, còn ETH (Ether) là đồng coin gốc dùng để trả phí gas và staking trên mạng này.","basics",1],["flash-loan","Flash loan (Vay nhanh)","Flash loan là khoản vay không cần thế chấp trong DeFi, với điều kiện vay và trả cả gốc lẫn phí trong cùng một giao dịch; nếu không trả đủ, toàn bộ giao dịch bị hủy.","defi",1],["fomo","FOMO (sợ bỏ lỡ)","FOMO (fear of missing out) là nỗi sợ bỏ lỡ cơ hội, khiến người giao dịch vội mua một tài sản đang tăng nóng mà không có kế hoạch, thường ở mức giá đã cao.","basics",1],["fud","FUD (sợ hãi, bất an, nghi ngờ)","FUD (Fear, Uncertainty, Doubt) là thông tin hoặc tâm lý gây sợ hãi, bất an và nghi ngờ về một dự án hay thị trường, có thể đúng sự thật hoặc bị phóng đại để làm giá giảm.","basics",1],["funding-rate","Funding rate (Tỷ lệ funding)","Funding rate là khoản thanh toán định kỳ giữa phe long và phe short trong hợp đồng tương lai vĩnh cửu, giúp giá hợp đồng bám sát giá spot.","derivatives",1],["index-price","Giá chỉ số (Index price)","Giá chỉ số (index price) là giá trung bình có trọng số của một tài sản trên nhiều sàn spot lớn, được dùng làm tham chiếu cho giá đánh dấu và funding rate.","derivatives",1],["mark-price","Giá đánh dấu (Mark price)","Giá đánh dấu (mark price) là giá tham chiếu mà sàn dùng để tính lãi lỗ chưa thực hiện và quyết định thanh lý, được xây dựng từ giá chỉ số của nhiều sàn spot.","derivatives",1],["last-price","Giá giao dịch cuối (Last price)","Giá giao dịch cuối (last price) là mức giá của lệnh khớp gần nhất trên sổ lệnh của một sàn, chính là con số giá bạn thấy thay đổi liên tục trên ứng dụng.","derivatives",1],["liquidation-price","Giá thanh lý (Liquidation price)","Giá thanh lý là mức giá đánh dấu mà tại đó vị thế có đòn bẩy của bạn sẽ bị sàn tự động đóng do ký quỹ không còn đủ.","derivatives",1],["auto-deleveraging","Giảm đòn bẩy tự động (ADL)","Giảm đòn bẩy tự động (ADL) là cơ chế cuối cùng của sàn: khi quỹ bảo hiểm không đủ bù lỗ từ một vị thế bị thanh lý, sàn tự đóng một phần vị thế đang lãi ở phía đối diện.","derivatives",1],["demo-trading","Giao dịch demo (tài khoản thử)","Giao dịch demo là chế độ giao dịch bằng tiền ảo trên giao diện giống thật, giúp bạn luyện thao tác đặt lệnh, dùng đòn bẩy và quản lý rủi ro mà không mất tiền thật.","exchange-features",1],["margin-trading","Giao dịch ký quỹ (Margin trading)","Giao dịch ký quỹ là việc vay thêm vốn từ sàn, dùng tài sản của bạn làm tài sản đảm bảo, để mở vị thế lớn hơn số tiền bạn có.","derivatives",1],["p2p-trading","Giao dịch P2P (C2C)","Giao dịch P2P là hình thức mua bán crypto trực tiếp giữa hai người dùng trên một nền tảng, trong đó sàn giữ coin của người bán làm bảo đảm cho tới khi người mua thanh toán xong.","exchange-features",1],["spot-trading","Giao dịch spot (Spot trading)","Giao dịch spot (spot trading) là mua bán tài sản crypto để nhận ngay quyền sở hữu thật ở giá hiện tại, không dùng hợp đồng và mặc định không có đòn bẩy.","trading",1],["geo-restrictions","Giới hạn khu vực (geo-restrictions)","Giới hạn khu vực là danh sách quốc gia hoặc vùng lãnh thổ mà một sàn hay dịch vụ crypto không phục vụ hoặc chỉ phục vụ một phần sản phẩm, do yêu cầu pháp lý.","regulation",1],["hash-rate","Hash rate (tốc độ băm)","Hash rate là tổng sức mạnh tính toán mà các máy đào dùng để bảo vệ một blockchain proof of work, đo bằng số phép băm mỗi giây.","onchain",1],["time-in-force","Hiệu lực lệnh (Time in force: GTC, IOC, FOK)","Time in force (hiệu lực lệnh) là thiết lập quy định một lệnh giới hạn tồn tại bao lâu và xử lý thế nào nếu không khớp ngay, phổ biến nhất là GTC, IOC và FOK.","trading",1],["hodl","HODL (giữ dài hạn)","HODL là cách nói trong cộng đồng crypto chỉ việc giữ tài sản lâu dài bất chấp biến động ngắn hạn, bắt nguồn từ một lỗi chính tả của chữ hold trên diễn đàn Bitcoin năm 2013.","basics",1],["support-and-resistance","Hỗ trợ và kháng cự (Support và Resistance)","Hỗ trợ và kháng cự là các vùng giá mà trước đây giá thường dừng giảm (hỗ trợ) hoặc dừng tăng (kháng cự), do lực mua hoặc lực bán tập trung ở đó.","trading",1],["coin-margined-futures","Hợp đồng ký quỹ bằng coin (Coin-M)","Hợp đồng ký quỹ bằng coin (Coin-M, hay hợp đồng nghịch đảo) là hợp đồng tương lai mà ký quỹ và lãi lỗ được tính bằng chính đồng coin cơ sở, ví dụ BTC, thay vì USDT.","derivatives",1],["usdt-margined-futures","Hợp đồng ký quỹ bằng USDT (USDT-M)","Hợp đồng ký quỹ bằng USDT (USDT-M, hay hợp đồng tuyến tính) là hợp đồng tương lai mà ký quỹ, lãi lỗ và phí đều tính bằng USDT.","derivatives",1],["open-interest","Hợp đồng mở (Open interest)","Hợp đồng mở (open interest, OI) là tổng số lượng hoặc giá trị các hợp đồng phái sinh đang còn mở và chưa được đóng hay tất toán tại một thời điểm.","derivatives",1],["smart-contract","Hợp đồng thông minh (Smart contract)","Hợp đồng thông minh (smart contract) là chương trình được triển khai trên blockchain, tự động thực hiện các điều kiện đã lập trình khi có giao dịch gọi tới mà không cần bên trung gian.","basics",1],["futures-contract","Hợp đồng tương lai (Futures)","Hợp đồng tương lai là thỏa thuận mua hoặc bán một tài sản theo giá xác định, cho phép bạn kiếm lời từ biến động giá mà không cần sở hữu tài sản thật.","derivatives",1],["delivery-futures","Hợp đồng tương lai giao sau (Delivery futures)","Hợp đồng tương lai giao sau là hợp đồng có ngày đáo hạn cố định, ví dụ theo tuần hoặc theo quý, và được tất toán theo giá chỉ số vào thời điểm đáo hạn.","derivatives",1],["perpetual-futures","Hợp đồng tương lai vĩnh cửu (Perpetual)","Hợp đồng tương lai vĩnh cửu (perpetual) là hợp đồng tương lai không có ngày đáo hạn, dùng cơ chế funding rate để giữ giá hợp đồng bám sát giá spot.","derivatives",1],["stock-perpetuals","Hợp đồng vĩnh cửu cổ phiếu (stock perpetuals)","Hợp đồng vĩnh cửu cổ phiếu là hợp đồng tương lai không có ngày đáo hạn, theo dõi giá một cổ phiếu hoặc chỉ số chứng khoán và được giao dịch bằng ký quỹ crypto như USDT.","tokenized-assets",1],["delisting","Hủy niêm yết (delisting)","Hủy niêm yết là việc sàn giao dịch ngừng hỗ trợ một token hoặc cặp giao dịch, thường kèm thời hạn để người dùng đóng vị thế, bán hoặc rút token ra ngoài.","exchange-features",1],["public-key","Khóa công khai (Public key)","Khóa công khai là khóa được tính ra từ khóa riêng tư, có thể chia sẻ công khai, dùng để mọi người xác minh chữ ký của bạn và để tạo ra địa chỉ ví.","wallets-security",1],["private-key","Khóa riêng tư (Private key)","Khóa riêng tư là một số bí mật rất lớn dùng để ký giao dịch và chứng minh bạn sở hữu một địa chỉ ví; ai biết khóa này có thể chuyển toàn bộ tài sản đi.","wallets-security",1],["trading-volume","Khối lượng giao dịch (Volume)","Khối lượng giao dịch là tổng giá trị hoặc số lượng một tài sản đã được mua bán trong một khoảng thời gian, thường tính trong 24 giờ.","trading",1],["initial-margin","Ký quỹ ban đầu (Initial margin)","Ký quỹ ban đầu là số tiền tối thiểu bạn phải đặt cọc để mở một vị thế có đòn bẩy, bằng giá trị vị thế chia cho đòn bẩy.","derivatives",1],["cross-margin","Ký quỹ chéo (Cross margin)","Ký quỹ chéo là chế độ trong đó toàn bộ số dư khả dụng của tài khoản được dùng chung làm ký quỹ cho các vị thế, giúp hạn chế thanh lý sớm nhưng có thể khiến bạn mất cả tài khoản.","derivatives",1],["isolated-margin","Ký quỹ cô lập (Isolated margin)","Ký quỹ cô lập là chế độ trong đó mỗi vị thế có một khoản ký quỹ riêng, nên nếu bị thanh lý bạn chỉ mất phần ký quỹ đã gán cho vị thế đó.","derivatives",1],["portfolio-margin","Ký quỹ danh mục (Portfolio margin)","Ký quỹ danh mục là chế độ tính ký quỹ dựa trên rủi ro tổng thể của cả danh mục, cho phép các vị thế phòng hộ lẫn nhau được giảm yêu cầu ký quỹ.","derivatives",1],["maintenance-margin","Ký quỹ duy trì (Maintenance margin)","Ký quỹ duy trì là mức ký quỹ tối thiểu bạn phải giữ để vị thế có đòn bẩy không bị thanh lý.","derivatives",1],["kyc","KYC (xác minh danh tính khách hàng)","KYC là quy trình sàn giao dịch hoặc tổ chức tài chính xác minh danh tính người dùng bằng giấy tờ tùy thân, ảnh khuôn mặt và đôi khi là địa chỉ cư trú.","regulation",1],["unrealized-pnl","Lãi lỗ chưa thực hiện (Unrealized PnL)","Lãi lỗ chưa thực hiện (unrealized PnL) là khoản lãi hoặc lỗ trên giấy của một vị thế đang mở, tính theo giá hiện tại, và chỉ trở thành lãi lỗ thật khi bạn đóng vị thế.","derivatives",1],["launchpad","Launchpad (mở bán token)","Launchpad là nền tảng mở bán token mới, nơi người dùng đăng ký mua token của dự án trước khi niêm yết, thường với giá cố định và số lượng phân bổ có hạn.","exchange-features",1],["launchpool","Launchpool","Launchpool là chương trình trên sàn cho phép bạn khóa token như BNB hay stablecoin trong một thời gian để nhận miễn phí token mới của dự án sắp niêm yết.","exchange-features",1],["layer-1","Layer 1 (L1, blockchain lớp 1)","Layer 1 (L1) là blockchain nền tảng tự xử lý và xác nhận giao dịch bằng cơ chế đồng thuận riêng, có coin gốc riêng, như Bitcoin, Ethereum, Solana hay BNB Chain.","basics",1],["layer-2","Layer 2 (L2, giải pháp lớp 2)","Layer 2 (L2) là mạng xây trên một blockchain lớp 1, xử lý giao dịch bên ngoài chuỗi chính rồi gửi kết quả gom lại về L1, giúp giao dịch nhanh hơn và phí rẻ hơn.","basics",1],["stop-loss","Lệnh cắt lỗ (Stop-loss)","Lệnh cắt lỗ (stop-loss) là lệnh tự động đóng vị thế khi giá chạm một mức bạn đặt trước, nhằm giới hạn khoản lỗ trong trường hợp thị trường đi ngược kỳ vọng.","trading",1],["trailing-stop","Lệnh cắt lỗ động (Trailing stop)","Lệnh cắt lỗ động (trailing stop) là lệnh dừng có giá kích hoạt tự động di chuyển theo giá khi giá đi đúng hướng, giữ một khoảng cách cố định, và chỉ kích hoạt khi giá đảo chiều đủ khoảng cách đó.","trading",1],["post-only-order","Lệnh chỉ đặt (Post-only)","Lệnh post-only là lệnh giới hạn chỉ được chấp nhận nếu nó nằm chờ trong sổ lệnh làm maker; nếu lệnh sẽ khớp ngay và trở thành taker, sàn tự động hủy hoặc điều chỉnh nó.","trading",1],["reduce-only-order","Lệnh chỉ giảm vị thế (Reduce-only)","Lệnh chỉ giảm vị thế (reduce-only) là tùy chọn khiến lệnh chỉ được phép đóng bớt hoặc đóng hết vị thế hiện có, không bao giờ mở thêm hay mở vị thế ngược chiều.","derivatives",1],["take-profit","Lệnh chốt lời (Take-profit)","Lệnh chốt lời (take-profit) là lệnh tự động đóng toàn bộ hoặc một phần vị thế khi giá đạt mức lợi nhuận bạn đặt trước, giúp bạn khóa lãi mà không cần theo dõi màn hình liên tục.","trading",1],["stop-limit-order","Lệnh dừng giới hạn (Stop-limit)","Lệnh dừng giới hạn (stop-limit) là lệnh có hai mức giá: khi giá chạm giá kích hoạt (stop), sàn đặt một lệnh giới hạn ở giá giới hạn (limit) bạn đã chọn, thay vì một lệnh thị trường.","trading",1],["limit-order","Lệnh giới hạn (Limit order)","Lệnh giới hạn (limit order) là lệnh mua hoặc bán ở mức giá bạn chỉ định hoặc tốt hơn; lệnh chỉ khớp khi thị trường chạm mức giá đó, nếu không sẽ nằm chờ trong sổ lệnh.","trading",1],["oco-order","Lệnh OCO (One-cancels-the-other)","Lệnh OCO (one-cancels-the-other) là cặp hai lệnh được đặt cùng lúc, thường một chốt lời và một cắt lỗ; khi một lệnh khớp hoặc kích hoạt, lệnh còn lại tự động bị hủy.","trading",1],["market-order","Lệnh thị trường (Market order)","Lệnh thị trường (market order) là lệnh mua hoặc bán ngay lập tức ở giá tốt nhất hiện có trong sổ lệnh, ưu tiên tốc độ khớp thay vì kiểm soát giá.","trading",1],["long-and-short","Long và Short (Vị thế mua và bán)","Long là mở vị thế kiếm lời khi giá tăng, short là mở vị thế kiếm lời khi giá giảm; hai thuật ngữ này dùng phổ biến trong giao dịch hợp đồng tương lai và ký quỹ.","derivatives",1],["pig-butchering-scam","Lừa đảo “nuôi heo” (Pig-butchering scam)","Lừa đảo “nuôi heo” là chiêu lừa kéo dài, kẻ gian làm quen, xây dựng lòng tin hoặc tình cảm qua mạng rồi dẫn nạn nhân vào nền tảng đầu tư crypto giả để rút sạch tiền.","wallets-security",1],["phishing","Lừa đảo giả mạo (Phishing)","Phishing là hình thức lừa đảo giả mạo sàn, ví, dự án hoặc người quen để lừa bạn nhập mật khẩu, mã 2FA, cụm từ khôi phục hoặc ký giao dịch có hại.","wallets-security",1],["anti-phishing-code","Mã chống lừa đảo (Anti-phishing code)","Mã chống lừa đảo là chuỗi ký tự riêng bạn tự đặt trên sàn, sau đó sàn chèn nó vào mọi email chính thức để bạn phân biệt email thật với email giả mạo.","wallets-security",1],["transaction-hash","Mã giao dịch (Transaction hash, TxID)","Mã giao dịch (TxID hay TxHash) là chuỗi ký tự duy nhất định danh một giao dịch trên blockchain, dùng để tra cứu trạng thái, số tiền, phí và số xác nhận của giao dịch đó.","wallets-security",1],["referral-code","Mã giới thiệu (hoàn phí giao dịch)","Mã giới thiệu là mã bạn nhập khi đăng ký sàn để liên kết tài khoản với người hoặc đối tác giới thiệu, thường giúp bạn được hoàn một phần phí giao dịch hoặc nhận ưu đãi người mới.","exchange-features",1],["blockchain-network","Mạng nạp rút (Chọn mạng blockchain)","Mạng nạp rút là blockchain cụ thể mà một đồng coin được chuyển qua, ví dụ USDT có thể đi trên Tron (TRC20), Ethereum (ERC20) hay BNB Chain (BEP20); bên gửi và bên nhận phải dùng cùng mạng.","wallets-security",1],["margin-call","Margin call (Cảnh báo ký quỹ)","Margin call là cảnh báo từ sàn khi ký quỹ của bạn giảm gần mức ký quỹ duy trì, yêu cầu bạn nạp thêm ký quỹ hoặc giảm vị thế để tránh bị thanh lý.","derivatives",1],["memecoin","Memecoin (meme coin)","Memecoin là đồng tiền mã hóa lấy cảm hứng từ meme, trò đùa hay văn hóa mạng, giá trị chủ yếu đến từ cộng đồng và sự chú ý thay vì sản phẩm hay dòng tiền thực.","basics",1],["memo-tag","Memo / Tag (Destination tag)","Memo hay tag là mã bổ sung đi kèm địa chỉ ví trên một số blockchain như XRP, XLM, TON, ATOM, giúp sàn biết khoản nạp vào địa chỉ chung thuộc về tài khoản nào.","wallets-security",1],["mempool","Mempool (vùng chờ giao dịch)","Mempool là nơi các giao dịch đã được phát lên mạng nhưng chưa được đưa vào khối nằm chờ, trước khi thợ đào hoặc validator chọn để xác nhận.","onchain",1],["mev","MEV (Giá trị khai thác tối đa)","MEV là phần lợi nhuận mà người sắp xếp giao dịch trong khối, như validator hay bot tìm kiếm, có thể thu được bằng cách chèn, sắp xếp lại hoặc loại bỏ giao dịch.","defi",1],["mica","MiCA (Luật thị trường tài sản mã hóa của EU)","MiCA là bộ quy định chung của Liên minh châu Âu về tài sản mã hóa, đặt ra yêu cầu cấp phép cho nhà cung cấp dịch vụ và quy tắc riêng cho stablecoin.","regulation",1],["token-unlock","Mở khóa token (Token unlock)","Mở khóa token (token unlock) là thời điểm một lượng token trước đây bị khóa theo lịch vesting được phép chuyển và bán, thường là phần của đội ngũ, nhà đầu tư hoặc quỹ dự án.","basics",1],["nft","NFT (Token không thể thay thế)","NFT là token độc nhất trên blockchain, mỗi token có mã định danh riêng và không thể đổi ngang với token khác, thường dùng để đại diện cho tác phẩm số, vật phẩm game, vé hoặc tư cách thành viên.","defi",1],["circulating-supply","Nguồn cung lưu hành (Circulating supply)","Nguồn cung lưu hành (circulating supply) là số lượng coin hoặc token đang thực sự có trên thị trường và có thể giao dịch, không tính phần bị khóa, chưa phát hành hoặc đã bị đốt.","basics",1],["market-maker","Nhà tạo lập thị trường (Market maker)","Nhà tạo lập thị trường (market maker) là cá nhân hoặc tổ chức liên tục đặt lệnh mua và lệnh bán cho một tài sản để cung cấp thanh khoản và kiếm lời từ chênh lệch giá.","trading",1],["token-listing","Niêm yết token (listing)","Niêm yết token là việc một sàn giao dịch chính thức thêm một token vào danh sách để người dùng có thể nạp, rút và giao dịch với các cặp nhất định.","exchange-features",1],["node","Node (nút mạng blockchain)","Node là máy tính chạy phần mềm của một blockchain, lưu dữ liệu chuỗi, kiểm tra giao dịch và khối theo quy tắc của mạng, rồi chia sẻ chúng với các node khác.","onchain",1],["oracle","Oracle (Nguồn dữ liệu blockchain)","Oracle là dịch vụ đưa dữ liệu bên ngoài như giá tài sản, kết quả sự kiện hay số ngẫu nhiên vào blockchain để hợp đồng thông minh sử dụng.","defi",1],["perp-dex","Perp DEX (Sàn hợp đồng vĩnh cửu phi tập trung)","Perp DEX là sàn phi tập trung cho phép giao dịch hợp đồng tương lai vĩnh cửu có đòn bẩy ngay trên blockchain, ký quỹ và thanh toán bằng ví của bạn thay vì tài khoản sàn tập trung.","defi",1],["on-chain-analysis","Phân tích on-chain","Phân tích on-chain là việc đọc dữ liệu công khai trên blockchain như giao dịch, số dư ví và dòng tiền ra vào sàn để hiểu hành vi của người tham gia thị trường.","onchain",1],["gas-fee","Phí gas (Gas fee)","Phí gas là khoản phí bạn trả cho mạng blockchain để xử lý một giao dịch hoặc thao tác với hợp đồng thông minh, tính bằng coin gốc của mạng như ETH trên Ethereum.","basics",1],["maker-taker-fees","Phí maker và phí taker (Maker/Taker fee)","Phí maker và phí taker là hai mức phí giao dịch khác nhau: maker trả phí khi lệnh của bạn nằm chờ trên sổ lệnh và tạo thêm thanh khoản, taker trả phí khi lệnh của bạn khớp ngay với lệnh có sẵn.","trading",1],["withdrawal-fee","Phí rút tiền (withdrawal fee)","Phí rút tiền là khoản phí sàn thu khi bạn chuyển crypto từ tài khoản sàn ra ví hoặc sàn khác, thường là một số coin cố định tùy theo mạng blockchain bạn chọn.","exchange-features",1],["hedging","Phòng hộ (Hedging)","Phòng hộ (hedging) là việc mở một vị thế ngược chiều để giảm rủi ro biến động giá của tài sản bạn đang nắm giữ, đổi lại bằng việc hạn chế phần lợi nhuận.","derivatives",1],["liquidity-pool","Pool thanh khoản (Liquidity pool)","Pool thanh khoản là kho token được khóa trong hợp đồng thông minh, do nhiều người cùng góp vào, để người khác giao dịch, vay hoặc swap, đổi lại người góp nhận một phần phí.","defi",1],["position-sizing","Quản lý khối lượng vị thế (Position sizing)","Position sizing là cách xác định bạn nên mở một lệnh lớn bao nhiêu, dựa trên số tiền bạn chấp nhận mất nếu lệnh chạm cắt lỗ.","trading",1],["insurance-fund","Quỹ bảo hiểm (Insurance fund)","Quỹ bảo hiểm là khoản dự trữ của sàn dùng để bù phần lỗ khi một vị thế bị thanh lý ở giá tệ hơn giá phá sản, nhằm tránh chuyển khoản lỗ đó sang người giao dịch khác.","derivatives",1],["options","Quyền chọn crypto (Options)","Quyền chọn crypto là hợp đồng cho người mua quyền, nhưng không bắt buộc, mua (call) hoặc bán (put) một tài sản ở mức giá định trước trong hoặc tại một thời điểm định trước.","derivatives",1],["restaking","Restaking (Tái staking)","Restaking là việc dùng lại ETH đã stake hoặc token stake thanh khoản để bảo đảm an ninh thêm cho các dịch vụ khác, nhận thêm phần thưởng nhưng chịu thêm rủi ro bị phạt.","defi",1],["rug-pull","Rug pull (Rút thảm)","Rug pull là khi đội ngũ dự án crypto đột ngột rút thanh khoản, bán tháo token hoặc biến mất cùng tiền của nhà đầu tư, khiến giá token gần như về 0.","wallets-security",1],["centralized-exchange","Sàn giao dịch tập trung (CEX)","Sàn giao dịch tập trung (CEX) là nền tảng do một công ty vận hành, giữ tài sản của người dùng và khớp lệnh mua bán trên sổ lệnh nội bộ, như Binance, OKX, Bybit hay Bitget.","trading",1],["no-kyc-exchange","Sàn không KYC","Sàn không KYC là nơi cho phép giao dịch hoặc rút crypto mà không cần xác minh danh tính, thường trong một hạn mức nhất định hoặc thông qua mô hình phi tập trung.","regulation",1],["dex","Sàn phi tập trung (DEX)","Sàn phi tập trung (DEX) là nơi giao dịch crypto trực tiếp từ ví của bạn qua hợp đồng thông minh, không cần nạp tiền vào tài khoản của một công ty trung gian.","defi",1],["satoshi","Satoshi (sats)","Satoshi (sats) là đơn vị nhỏ nhất của Bitcoin, với 1 BTC bằng 100.000.000 satoshi, giúp bạn mua và chuyển những phần rất nhỏ của một đồng BTC.","basics",1],["short-squeeze","Short squeeze (Ép short)","Short squeeze là hiện tượng giá tăng nhanh buộc nhiều người đang short phải đóng vị thế hoặc bị thanh lý, và lệnh mua bắt buộc của họ lại đẩy giá tăng tiếp.","derivatives",1],["order-book","Sổ lệnh (Order book)","Sổ lệnh (order book) là danh sách theo thời gian thực của tất cả lệnh mua và lệnh bán đang chờ khớp cho một cặp giao dịch, sắp xếp theo mức giá và khối lượng.","trading",1],["block-confirmations","Số xác nhận khối (Block confirmations)","Số xác nhận khối là số khối đã được thêm vào blockchain kể từ khối chứa giao dịch của bạn; càng nhiều xác nhận thì giao dịch càng khó bị đảo ngược.","wallets-security",1],["stablecoin","Stablecoin (Đồng tiền ổn định)","Stablecoin là đồng crypto được thiết kế để giữ giá ổn định so với một tài sản tham chiếu, phổ biến nhất là 1 USD, như USDT và USDC.","stablecoins",1],["crypto-backed-stablecoin","Stablecoin thế chấp bằng crypto","Stablecoin thế chấp bằng crypto là stablecoin được đúc ra khi người dùng khóa tài sản crypto như ETH vào hợp đồng thông minh với giá trị lớn hơn số stablecoin nhận được.","stablecoins",1],["algorithmic-stablecoin","Stablecoin thuật toán","Stablecoin thuật toán là stablecoin cố giữ giá 1 USD chủ yếu bằng quy tắc phát hành và đốt token tự động, thay vì có đủ tài sản dự trữ bảo chứng phía sau.","stablecoins",1],["staking","Staking","Staking là việc khóa coin của một blockchain proof-of-stake để giúp xác thực giao dịch và bảo vệ mạng lưới, đổi lại nhận phần thưởng bằng chính coin đó.","defi",1],["liquid-staking","Staking thanh khoản (Liquid staking)","Staking thanh khoản là cách stake coin qua một giao thức và nhận lại token đại diện như stETH, có thể giao dịch hoặc dùng trong DeFi trong khi coin gốc vẫn đang được stake.","defi",1],["unified-trading-account","Tài khoản giao dịch hợp nhất (UTA)","Tài khoản giao dịch hợp nhất là loại tài khoản gộp spot, ký quỹ, hợp đồng tương lai và quyền chọn vào một ví duy nhất, cho phép dùng chung tài sản làm ký quỹ.","exchange-features",1],["sub-account","Tài khoản phụ (sub-account)","Tài khoản phụ là tài khoản con được tạo dưới tài khoản chính trên sàn, có số dư và vị thế riêng, giúp bạn tách biệt chiến lược, rủi ro và quyền truy cập.","exchange-features",1],["real-world-assets","Tài sản thực (RWA)","Tài sản thực, hay RWA, là các tài sản ngoài blockchain như trái phiếu, vàng, bất động sản hay khoản vay được token hóa để có thể nắm giữ và giao dịch trên chuỗi.","tokenized-assets",1],["amm","Tạo lập thị trường tự động (AMM)","AMM (tạo lập thị trường tự động) là cơ chế của nhiều DEX dùng công thức toán học và pool thanh khoản để định giá và khớp giao dịch, thay cho sổ lệnh mua bán truyền thống.","defi",1],["liquidity","Thanh khoản (Liquidity)","Thanh khoản là mức độ dễ dàng mua hoặc bán một tài sản với số lượng lớn mà giá không bị đẩy đi nhiều.","trading",1],["liquidation","Thanh lý (Liquidation)","Thanh lý (hay cháy tài khoản) là khi sàn tự động đóng vị thế có đòn bẩy của bạn vì ký quỹ không còn đủ đáp ứng mức ký quỹ duy trì.","derivatives",1],["bear-market","Thị trường giảm giá (Bear market)","Thị trường giảm giá (bear market) là giai đoạn giá giảm kéo dài, thường hơn 20% từ đỉnh, kèm tâm lý bi quan, khối lượng giao dịch thấp và dòng tiền rút khỏi thị trường.","basics",1],["bull-market","Thị trường tăng giá (Bull market)","Thị trường tăng giá (bull market) là giai đoạn giá tài sản đi lên kéo dài, đi kèm tâm lý lạc quan, khối lượng giao dịch tăng và dòng tiền mới đổ vào thị trường.","basics",1],["cryptocurrency","Tiền mã hóa (Cryptocurrency)","Tiền mã hóa (cryptocurrency) là tài sản số được ghi nhận trên blockchain, chuyển trực tiếp giữa các ví mà không cần ngân hàng trung gian, và quyền sở hữu được bảo vệ bằng khóa riêng tư.","basics",1],["wrapped-token","Token gói (Wrapped token)","Token gói là token đại diện cho một tài sản khác theo tỷ lệ 1:1, ví dụ WBTC đại diện cho BTC trên Ethereum, giúp tài sản đó dùng được trên blockchain hoặc trong ứng dụng vốn không hỗ trợ nó.","defi",1],["governance-token","Token quản trị (Governance token)","Token quản trị là token cho người nắm giữ quyền đề xuất và bỏ phiếu về các thay đổi của một giao thức hay DAO, ví dụ UNI của Uniswap hay AAVE của Aave.","defi",1],["tokenomics","Tokenomics (kinh tế học token)","Tokenomics là toàn bộ thiết kế kinh tế của một token: tổng cung, cách phân bổ, lịch mở khóa, cơ chế phát hành và đốt, cùng công dụng khiến người dùng cần giữ hoặc dùng token đó.","basics",1],["impermanent-loss","Tổn thất tạm thời (Impermanent loss)","Tổn thất tạm thời là phần giá trị bạn bị thiệt khi cung cấp thanh khoản cho pool so với việc chỉ giữ nguyên hai token, phát sinh khi giá của chúng thay đổi lệch nhau.","defi",1],["total-value-locked","Tổng giá trị khóa (TVL)","TVL (tổng giá trị khóa) là tổng giá trị tài sản crypto đang được gửi trong một giao thức DeFi hoặc một blockchain, thường tính bằng USD, dùng để đo quy mô và mức độ sử dụng.","defi",1],["tokenized-treasuries","Trái phiếu chính phủ token hóa (tokenized treasuries)","Trái phiếu chính phủ token hóa là token đại diện cho phần sở hữu trong quỹ hoặc danh mục trái phiếu kho bạc ngắn hạn, thường là của Mỹ, mang lại lợi suất ngay trên blockchain.","tokenized-assets",1],["travel-rule","Travel rule (quy tắc chuyển tiền)","Travel rule là quy định yêu cầu các nhà cung cấp dịch vụ tài sản ảo gửi kèm thông tin người gửi và người nhận khi chuyển crypto giữa các tổ chức với nhau.","regulation",1],["slippage","Trượt giá (Slippage)","Trượt giá (slippage) là phần chênh lệch giữa giá bạn dự kiến khi đặt lệnh và giá khớp thực tế, xảy ra khi thanh khoản không đủ hoặc giá thay đổi trong lúc lệnh đang được xử lý.","trading",1],["long-short-ratio","Tỷ lệ Long/Short (Long/short ratio)","Tỷ lệ long/short là chỉ số so sánh số tài khoản hoặc khối lượng vị thế đang long với số đang short trên một sàn, dùng để đọc tâm lý người giao dịch phái sinh.","derivatives",1],["risk-reward-ratio","Tỷ lệ rủi ro/lợi nhuận (Risk-reward ratio)","Tỷ lệ rủi ro/lợi nhuận (R:R) so sánh số tiền bạn có thể mất nếu chạm cắt lỗ với số tiền bạn có thể lãi nếu chạm chốt lời trong cùng một lệnh.","trading",1],["usdc","USDC (USD Coin)","USDC là stablecoin do công ty Circle phát hành, neo 1:1 với đô la Mỹ và được đảm bảo bằng tiền mặt cùng tài sản ngắn hạn tương đương tiền.","stablecoins",1],["usdt","USDT (Tether)","USDT là stablecoin do công ty Tether phát hành, neo theo tỷ lệ 1 USDT bằng 1 USD và là đồng ổn định được giao dịch nhiều nhất trên các sàn crypto.","stablecoins",1],["validator","Validator (trình xác thực)","Validator (trình xác thực) là node trên blockchain bằng chứng cổ phần, khóa coin làm tài sản đảm bảo để đề xuất, kiểm tra và bỏ phiếu cho các khối mới, đổi lại nhận phần thưởng.","basics",1],["tokenized-gold","Vàng token hóa (tokenized gold)","Vàng token hóa là token trên blockchain đại diện cho quyền sở hữu một lượng vàng vật chất cụ thể được lưu giữ trong kho, phổ biến nhất là PAXG và XAUT.","tokenized-assets",1],["vasp","VASP (nhà cung cấp dịch vụ tài sản ảo)","VASP là tổ chức cung cấp dịch vụ liên quan đến tài sản ảo cho người khác, như sàn giao dịch, dịch vụ lưu ký hoặc chuyển đổi crypto, và chịu các nghĩa vụ quản lý như KYC, AML.","regulation",1],["hardware-wallet","Ví cứng (Hardware wallet)","Ví cứng là thiết bị vật lý nhỏ chuyên lưu khóa riêng tư ngoại tuyến và ký giao dịch bên trong thiết bị, nên khóa không bao giờ lộ ra máy tính hay điện thoại.","wallets-security",1],["multisig-wallet","Ví đa chữ ký (Multisig wallet)","Ví đa chữ ký là ví cần nhiều khóa riêng tư cùng ký, ví dụ 2 trên 3 khóa, thì giao dịch mới được thực hiện, giúp không một khóa đơn lẻ nào có thể tự di chuyển tài sản.","wallets-security",1],["cold-wallet","Ví lạnh (Cold wallet)","Ví lạnh là cách lưu khóa riêng tư hoàn toàn ngoại tuyến, ví dụ trên ví cứng hoặc thiết bị không bao giờ kết nối mạng, để giảm tối đa rủi ro bị hack từ xa.","wallets-security",1],["custodial-wallet","Ví lưu ký (Custodial wallet)","Ví lưu ký là ví mà một bên thứ ba, thường là sàn giao dịch, giữ khóa riêng tư thay bạn; bạn truy cập tài sản bằng tài khoản và mật khẩu thay vì seed phrase.","wallets-security",1],["hot-wallet","Ví nóng (Hot wallet)","Ví nóng là ví crypto có khóa riêng tư nằm trên thiết bị hoặc máy chủ kết nối internet, giúp giao dịch nhanh nhưng dễ bị tấn công từ xa hơn ví lạnh.","wallets-security",1],["non-custodial-wallet","Ví phi lưu ký (Non-custodial wallet)","Ví phi lưu ký là loại ví crypto mà bạn tự giữ khóa riêng tư và cụm từ khôi phục, nên chỉ bạn mới có quyền ký giao dịch và di chuyển tài sản.","wallets-security",1],["crypto-wallet","Ví tiền mã hóa (Crypto wallet)","Ví tiền mã hóa là phần mềm hoặc thiết bị quản lý khóa riêng tư của bạn, cho phép bạn nhận, gửi và ký giao dịch với tài sản crypto trên blockchain.","wallets-security",1],["market-capitalization","Vốn hóa thị trường (Market cap)","Vốn hóa thị trường (market cap) của một đồng tiền mã hóa là giá hiện tại nhân với nguồn cung lưu hành, cho biết tổng giá trị thị trường đang định cho lượng coin đang lưu thông.","basics",1],["wash-trading","Wash trading (giao dịch giả)","Wash trading là việc một người hoặc một nhóm tự mua và tự bán cùng một tài sản với chính mình để tạo ra khối lượng giao dịch giả, khiến thị trường trông sôi động hơn thực tế.","trading",1],["two-factor-authentication","Xác thực hai yếu tố (2FA)","Xác thực hai yếu tố (2FA) là lớp bảo mật yêu cầu thêm một mã hoặc thiết bị ngoài mật khẩu khi đăng nhập, rút tiền hay đổi cài đặt, để kẻ chỉ có mật khẩu vẫn không vào được tài khoản.","wallets-security",1],["yield-farming","Yield farming (Canh tác lợi suất)","Yield farming là chiến lược đưa crypto vào các giao thức DeFi như pool thanh khoản hoặc nền tảng cho vay để nhận phí, lãi và token thưởng, thường di chuyển vốn tới nơi trả lợi suất cao.","defi",1]]});
